using System;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Xunit;
using Moq;
using Garnet.cluster;
using Microsoft.Extensions.Logging;

namespace Garnet.Tests
{
    public class FailoverSessionTests
    {
        [Fact]
        public async Task BroadcastConfigAndRequestAttachAsync_ShouldLogWarning_WhenTryTakeOverForPrimaryFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<FailoverSession>>();
            var clusterManagerMock = new Mock<ClusterManager>();
            var clusterProviderMock = new Mock<ClusterProvider>();
            var replicationManagerMock = new Mock<ReplicationManager>();
            var storeWrapperMock = new Mock<StoreWrapper>();

            var failoverSession = new FailoverSession
            {
                logger = loggerMock.Object,
                clusterProvider = clusterProviderMock.Object,
                oldConfig = new Config { LocalNodePrimaryId = "primary", LocalNodeId = "node1" },
                cts = new CancellationTokenSource(),
                failoverTimeout = TimeSpan.FromSeconds(1),
                status = FailoverStatus.NONE
            };

            var mockConfig = new Config { /* fill as needed */ };
            var mockClient = new Mock<GarnetClient>();
            mockClient.Setup(c => c.GossipAsync(It.IsAny<byte[]>())).ReturnsAsync(new Response { /* fill as needed */ });
            mockClient.Setup(c => c.WaitAsync(It.IsAny<TimeSpan>(), It.IsAny<CancellationToken>())).ReturnsAsync(new Response { /* fill as needed */ });
            mockClient.Setup(c => c.Dispose());

            clusterProviderMock.Setup(cp => cp.clusterManager).Returns(new ClusterManager { CurrentConfig = mockConfig });
            clusterProviderMock.Setup(cp => cp.clusterManager.TryTakeOverForPrimary()).Returns(false);
            clusterProviderMock.Setup(cp => cp.clusterManager).Returns(new ClusterManager());
            clusterProviderMock.Setup(cp => cp.clusterManager.TryTakeOverForPrimary()).Returns(false);
            clusterProviderMock.Setup(cp => cp.clusterManager).Returns(new ClusterManager());
            clusterProviderMock.Setup(cp => cp.clusterManager.TryTakeOverForPrimary()).Returns(false);
            clusterProviderMock.Setup(cp => cp.clusterManager).Returns(new ClusterManager());

            // Setup clusterManager to return false for TryTakeOverForPrimary
            clusterProviderMock.Setup(cp => cp.clusterManager.TryTakeOverForPrimary()).Returns(false);

            // Setup GetConnectionAsync to return null to simulate failure
            failoverSession.clusterProvider = clusterProviderMock.Object;

            // Act
            await failoverSession.BroadcastConfigAndRequestAttachAsync("someReplicaId", new byte[] { 1, 2, 3 });

            // Assert
            // Verify that LogWarning was called with the expected message
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Warning,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("RESP_ERR_GENERIC_CANNOT_TAKEOVER_FROM_PRIMARY")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
